@file:OptIn(kotlin.io.encoding.ExperimentalEncodingApi::class)

package dev.cluvex.zedsecure.domain.config

import kotlin.io.encoding.Base64

/**
 * NPVT1 compatibility transform. Table layout is derived from the MIT-licensed
 * npvt-terminal-converter reference implementation by TheLouisMahdi.
 * See docs/NPV_TUNNEL_SUPPORT.md and the third-party notice for attribution.
 */
internal object NpvtWhiteboxCipher {
    private val words: IntArray by lazy {
        val raw = Base64.Default.decode(
            listOf(
                "",
                "",
                "",
                ""
            ).joinToString(separator = ""),
        )
        require(raw.size == 36864 * 4) { "Invalid NPVT table payload" }
        IntArray(raw.size / 4) { i ->
            val p = i * 4
            ((raw[p].toInt() and 0xff) shl 24) or
                ((raw[p + 1].toInt() and 0xff) shl 16) or
                ((raw[p + 2].toInt() and 0xff) shl 8) or
                (raw[p + 3].toInt() and 0xff)
        }
    }

    private const val TY = 0
    private const val XOR = 4096
    private const val MBL = 28672
    private const val LAST = 32768
    private val shiftOrder = intArrayOf(0, 5, 10, 15, 4, 9, 14, 3, 8, 13, 2, 7, 12, 1, 6, 11)

    private fun shiftRows(input: ByteArray): ByteArray = ByteArray(16) { i -> input[shiftOrder[i]] }
    private fun ty(table: Int, value: Int) = words[TY + table * 256 + value]
    private fun mb(table: Int, value: Int) = words[MBL + table * 256 + value]
    private fun last(table: Int, value: Int) = words[LAST + table * 256 + value]
    private fun xor(table: Int, a: Int, b: Int) = words[XOR + table * 256 + a * 16 + b]

    private fun transform(block: ByteArray): ByteArray {
        var buf = shiftRows(block)
        for (round in 0 until 4) {
            val base = round * 4
            val a = ty(base, buf[base].toInt() and 0xff)
            val b = ty(base + 1, buf[base + 1].toInt() and 0xff)
            val c = ty(base + 2, buf[base + 2].toInt() and 0xff)
            val d = ty(base + 3, buf[base + 3].toInt() and 0xff)
            for (column in 0 until 4) {
                val t = round * 24 + column * 6
                val shiftHigh = 28 - column * 8
                val shiftLow = 24 - column * 8
                val n1 = (a ushr shiftHigh) and 15
                val n2 = (b ushr shiftHigh) and 15
                val n3 = (c ushr shiftHigh) and 15
                val n4 = (d ushr shiftHigh) and 15
                val hiPair = xor(t, n1, n2)
                val loPair = xor(t + 1, n3, n4)
                val m1 = (a ushr shiftLow) and 15
                val m2 = (b ushr shiftLow) and 15
                val m3 = (c ushr shiftLow) and 15
                val m4 = (d ushr shiftLow) and 15
                val lo = xor(t + 5, xor(t + 2, m1, m2), xor(t + 3, m3, m4))
                val hi = xor(t + 4, hiPair, loPair)
                buf[base + column] = (lo or (hi shl 4)).toByte()
            }
            val e = mb(base, buf[base].toInt() and 0xff)
            val f = mb(base + 1, buf[base + 1].toInt() and 0xff)
            val g = mb(base + 2, buf[base + 2].toInt() and 0xff)
            val h = mb(base + 3, buf[base + 3].toInt() and 0xff)
            for (column in 0 until 4) {
                val t = round * 24 + column * 6
                val shiftHigh = 28 - column * 8
                val shiftLow = 24 - column * 8
                val n1 = (e ushr shiftHigh) and 15
                val n2 = (f ushr shiftHigh) and 15
                val n3 = (g ushr shiftHigh) and 15
                val n4 = (h ushr shiftHigh) and 15
                val hi = xor(t + 4, xor(t, n1, n2), xor(t + 1, n3, n4))
                val m1 = (e ushr shiftLow) and 15
                val m2 = (f ushr shiftLow) and 15
                val m3 = (g ushr shiftLow) and 15
                val m4 = (h ushr shiftLow) and 15
                val lo = xor(t + 5, xor(t + 2, m1, m2), xor(t + 3, m3, m4))
                buf[base + column] = ((hi shl 4) or lo).toByte()
            }
        }
        buf = shiftRows(buf)
        for (i in 0 until 16) buf[i] = last(i, buf[i].toInt() and 0xff).toByte()
        return buf
    }

    fun decrypt(ciphertextWithNonce: ByteArray): ByteArray {
        require(ciphertextWithNonce.size >= 16) { "NPVT1 chunk is shorter than its nonce" }
        val counter = ciphertextWithNonce.copyOfRange(0, 16)
        val data = ciphertextWithNonce.copyOfRange(16, ciphertextWithNonce.size)
        val output = ByteArray(data.size)
        var stream = ByteArray(16)
        for (i in data.indices) {
            if (i % 16 == 0) {
                stream = transform(counter)
                for (p in 15 downTo 0) {
                    counter[p] = ((counter[p].toInt() and 0xff) + 1).toByte()
                    if ((counter[p].toInt() and 0xff) != 0) break
                }
            }
            output[i] = (stream[i % 16].toInt() xor data[i].toInt()).toByte()
        }
        return output
    }
}
